import {
	Component,
	Element,
	Fragment,
	Host,
	Listen,
	Method,
	Prop,
	State,
	Watch,
	h,
} from "@stencil/core";

import merge from "deepmerge";

import type { HbrPopover } from "../popover/popover";
import { preloadSanitizeHtml } from "../../utils/sanitizeHtml";

const LABEL_HEIGHT_TOP_OR_BOTTOM = 60;
const LABEL_WIDTH_LEFT_OR_RIGHT = 80;
const LABEL_TRUNCATE_WIDTH = 110;

import type { MatrixChartConfig } from "./matrix.d";

/**
 * @since 2.8.0
 * @status experimental
 * @part chart - The chart element
 * @part header - The header element
 * @part popover-body - The popover body element, check hbr-popover for more details
 * @part popover-popup - The popover popup element,  check hbr-popover for more details
 * @part popover-arrow - The popover arrow element,  check hbr-popover for more details
 * @part container - The container svg element
 *
 * @slot axis-label-left - Slot for left axis description
 * @slot axis-label-top - Slot for top axis description
 * @slot axis-label-right - Slot for right axis description
 * @slot axis-label-bottom - Slot for bottom axis description
 * @slot header - Slot for header
 * @slot header-title - Slot for header title
 * @slot header-action - Slot for header action
 * @slot footer - Slot for footer
 * @slot loading-state - Slot for loading state
 * @slot empty-state - Slot for empty state
 * @slot content - Slot for popover content
 * @slot control-panel - Slot for control panel on the right
 */
@Component({
	tag: "hbr-matrix-chart",
	styleUrl: "matrix.scss",
	shadow: true,
})
export class HbrMatrixChart {
	private matrixRuntime?: typeof import("./matrix-runtime");

	chartRef: HTMLElement;
	tooltipRef: HTMLHbrPopoverElement;
	boardRef: HTMLHbrChartBoardElement;
	controlRef: HTMLElement;
	labelTopRef: HTMLElement;
	labelLeftRef: HTMLElement;
	labelRightRef: HTMLElement;

	keyboardFocusedIndex = -1;

	@Element() private el: HTMLHbrMatrixChartElement;

	/** Chart configuration */
	@Prop({ mutable: true }) config: MatrixChartConfig = {
		data: [],
		statuses: {},
		axis: {
			left: { enabled: false },
			right: { enabled: false },
			top: { enabled: false },
			bottom: { enabled: false },
		},
		accessibility: { ariaLabel: () => "" },
	};
	/** Chart width */
	@Prop() width = "100%";
	/** Chart height */
	@Prop() height = "360px";

	/** Chart loading flag */
	@Prop() loading = false;

	@State() gridSize = {
		blockSize: 0,
		gapSize: 0,
		iconSize: 0,
	};

	@Prop({ mutable: true }) mode: "view" | "edit" = "view";

	@State() tooltipContent: HTMLElement;

	@Prop({ mutable: true }) selectedItems: {
		[key: string]: { status: string };
	} = {};

	/** Hovered items on hbr-popover if tooltipItemTemplate is used */
	@State() hoveredItems: {
		row: string;
		col: string;
		obj: unknown;
	} = { row: "", col: "", obj: {} };

	/** grid item popover props, check hbr-popover page for all available options */
	@Prop() popoverOptions: Partial<HbrPopover>;

	/** Final config before rendering */
	private fullConfig: MatrixChartConfig;

	async componentWillLoad() {
		const [matrixRuntime] = await Promise.all([
			import("./matrix-runtime"),
			preloadSanitizeHtml(),
		]);
		this.matrixRuntime = matrixRuntime;
	}

	componentDidLoad() {
		if (!this.matrixRuntime) {
			return;
		}

		//stencil bug https://github.com/ionic-team/stencil/issues/3193
		this.matrixRuntime.setForeignObjectAttributes(this.chartRef);

		const idx = this.fullConfig.grid?.itemSizes.findIndex(
			(size) => size === this.fullConfig.grid?.defaultSize,
		);
		if (idx !== -1) {
			this.gridSize.blockSize = this.fullConfig.grid?.itemSizes[idx];
			this.gridSize.gapSize = this.fullConfig.grid?.gapSizes[idx];
			this.gridSize.iconSize = this.fullConfig.grid?.iconSizes[idx];
			this.gridSize = JSON.parse(JSON.stringify(this.gridSize));
		}
	}

	onZooming = (isZoomIn: boolean) => {
		const { fullConfig } = this;
		const nextIndex =
			fullConfig.grid?.itemSizes.findIndex(
				(size) => size === this.gridSize.blockSize,
			) + (isZoomIn ? 1 : -1);
		if (nextIndex >= 0 && nextIndex < fullConfig.grid?.itemSizes.length) {
			const newSize = {
				blockSize: fullConfig.grid?.itemSizes[nextIndex],
				gapSize: fullConfig.grid?.gapSizes[nextIndex],
				iconSize: fullConfig.grid?.iconSizes[nextIndex],
			};

			this.gridSize = newSize;
		}
	};

	@Method()
	async selectAll() {
		if (!this.matrixRuntime) {
			return this.selectedItems;
		}

		const items = this.matrixRuntime.getAllEnabledCells(this.chartRef);

		items.forEach((item) => {
			const row = item.getAttribute("data-row");
			const col = item.getAttribute("data-col");
			const status = item.getAttribute("data-status") || "default";
			this.selectedItems = {
				[`${row}-${col}`]: { status: status },
				...this.selectedItems,
			};
			this.matrixRuntime.applyItemStyleFromStatus(
				item,
				"selected",
				"edit",
				this.fullConfig.statuses,
				this.gridSize.iconSize,
			);
		});
		return this.selectedItems;
	}

	@Method()
	async deselectAll() {
		if (!this.matrixRuntime) {
			return this.selectedItems;
		}

		this.selectedItems = {};
		const items = this.matrixRuntime.getAllEnabledCells(this.chartRef);
		items.forEach((item) => {
			this.matrixRuntime.applyItemStyleFromStatus(
				item,
				"default",
				"edit",
				this.fullConfig.statuses,
				this.gridSize.iconSize,
			);
		});
		return this.selectedItems;
	}

	onModeChange = (event) => {
		if (!this.matrixRuntime) {
			return;
		}

		this.keyboardFocusedIndex = -1;
		const items = this.matrixRuntime.getAllEnabledCells(this.chartRef);

		if (this.mode === "view") {
			this.mode = "edit";
			items.forEach((item) => {
				const status =
					item.getAttribute("data-selected") === "true"
						? "selected"
						: "default";
				this.matrixRuntime.applyItemStyleFromStatus(
					item,
					status,
					"edit",
					this.fullConfig.statuses,
					this.gridSize.iconSize,
				);
			});
			this.fullConfig?.onSwitchMode?.(event, this.mode);
		} else {
			this.mode = "view";
			items.forEach((item) => {
				this.matrixRuntime.applyItemStyleFromStatus(
					item,
					"default",
					"view",
					this.fullConfig.statuses,
					this.gridSize.iconSize,
				);
			});
			this.fullConfig?.onSwitchMode?.(event, this.mode, this.selectedItems);
		}
	};

	@Listen("click", { passive: true })
	handleOutsideClick() {
		if (!this.matrixRuntime) {
			return;
		}

		const item = this.chartRef.querySelector(
			`[data-index="${this.keyboardFocusedIndex}"]`,
		);
		if (item) {
			item.firstElementChild.removeAttribute("tabindex");
			(item.firstElementChild as HTMLDivElement).blur();
		}
		this.keyboardFocusedIndex = -1;

		const items = Array.from(
			this.chartRef.querySelectorAll(".grid-cell"),
		).filter(
			(r) => r.getAttribute("data-disabled") !== "true",
		) as SVGForeignObjectElement[];

		items.forEach((item) => {
			const status =
				item.getAttribute("data-selected") === "true" ? "selected" : "default";
			const mode = this.mode === "edit" ? "edit" : "view";
			this.matrixRuntime.applyItemStyleFromStatus(
				item,
				status,
				mode,
				this.fullConfig.statuses,
				this.gridSize.iconSize,
			);
		});
	}

	@Watch("gridSize")
	onGridSizeChange() {
		setTimeout(() => {
			this.matrixRuntime?.setForeignObjectAttributes(this.chartRef);
		}, 100);
	}

	showAxisTooltip = (event: MouseEvent, data) => {
		if (!this.matrixRuntime) {
			return;
		}

		this.tooltipContent = this.matrixRuntime.setDefaultAxisTooltipTemplate(
			h,
			data,
		);
		this.tooltipRef.open = true;
		this.tooltipRef.anchor = event.target as HTMLElement;
	};
	hideAxisTooltip = () => {
		this.tooltipRef.open = false;
	};

	renderChart = () => {
		if (!this.matrixRuntime) {
			return null;
		}

		const runtime = this.matrixRuntime;
		const { blockSize, gapSize, iconSize } = this.gridSize;

		const defaultConfig = runtime.getDefaultConfig(
			LABEL_HEIGHT_TOP_OR_BOTTOM,
			LABEL_WIDTH_LEFT_OR_RIGHT,
			this.showAxisTooltip,
			this.hideAxisTooltip,
			this.config.axis,
			LABEL_TRUNCATE_WIDTH,
		);

		this.fullConfig = merge(defaultConfig, this.config);
		const { axis, data = [] } = this.fullConfig;

		const rowLabels = runtime.getRowLabels(data);
		const colLabels = runtime.getColumnLabels(data);
		const complete2DAry = runtime.fillColIfEmpty(data, colLabels);

		this.fullConfig.eventListeners.view = runtime.getModeViewEventHandlers(
			this,
			complete2DAry,
			h,
		);
		this.fullConfig.eventListeners.edit =
			runtime.getModeEditEventHandlers(this);

		const labelHeight = axis.top.height || LABEL_HEIGHT_TOP_OR_BOTTOM;
		const labelWidth = axis.left.width || LABEL_WIDTH_LEFT_OR_RIGHT;

		const marginLeft = axis?.left?.enabled ? labelWidth : 0;
		const marginTop = axis?.top?.enabled ? labelHeight : 0;
		const { containerWidth, containerHeight } =
			runtime.calculateContainerDimensions(
				axis,
				complete2DAry,
				blockSize,
				gapSize,
			);
		const labelLeftWidth =
			this.labelLeftRef?.getBoundingClientRect().width || 0;
		const labelRightWidth =
			this.labelRightRef?.getBoundingClientRect().width || 0;

		const { onKeyDown } = runtime.getContainerKeyboardEvents(this);
		return (
			<Fragment>
				<div
					class="chart-matrix__label-top-container"
					ref={(el) => {
						this.labelTopRef = el;
					}}
					style={{
						marginLeft: `${
							axis?.left?.enabled ? labelWidth + labelLeftWidth : labelLeftWidth
						}px`,
						marginRight: `${
							axis?.right?.enabled
								? labelWidth + labelRightWidth
								: labelRightWidth
						}px`,
					}}
				>
					<slot name="axis-label-top" />
				</div>
				<div class="chart-matrix__label-center">
					<div
						class="chart-matrix__label-left-container"
						ref={(el) => {
							this.labelLeftRef = el;
						}}
						style={{
							marginTop: axis?.top?.enabled ? `${labelHeight}px` : "0",
						}}
					>
						<slot name="axis-label-left" />
					</div>
					<div class="chart-matrix__body">
						<svg
							xmlns="http://www.w3.org/2000/svg"
							role="application"
							width={containerWidth}
							height={containerHeight}
							tabindex={0}
							onKeyDown={onKeyDown}
						>
							<title />
							{axis?.top?.enabled &&
								runtime.generateAxisTop(
									colLabels,
									blockSize,
									gapSize,
									{
										...axis?.top,
										height: axis?.top.height || labelHeight,
									},
									marginLeft,
									this.el,
								)}

							{axis?.bottom?.enabled &&
								runtime.generateAxisBottom(
									colLabels,
									blockSize,
									gapSize,
									{
										...axis?.bottom,
										height: axis?.bottom.height || labelHeight,
									},
									marginTop + complete2DAry.length * (blockSize + gapSize),
									marginLeft,
									this.el,
								)}

							{axis?.left?.enabled &&
								runtime.generateAxisLegendLeft(
									rowLabels,
									blockSize,
									gapSize,
									{
										...axis?.left,
										width: axis?.left.width || labelWidth,
									},
									marginTop,
									this.el,
								)}

							{axis?.right?.enabled &&
								runtime.generateAxisRight(
									rowLabels,
									blockSize,
									gapSize,
									{
										...axis?.right,
										width: axis?.right.width || labelWidth,
									},
									marginTop,
									marginLeft +
										complete2DAry[0].data.length * (blockSize + gapSize) -
										gapSize,
									this.el,
								)}
							{runtime.generateDataBlock(
								complete2DAry,
								blockSize,
								gapSize,
								iconSize,
								marginLeft,
								marginTop,
								this.mode,
								this.fullConfig,
								this.selectedItems,
							)}
						</svg>
					</div>
					<div
						class="chart-matrix__label-right-container"
						ref={(el) => {
							this.labelRightRef = el;
						}}
						style={{
							marginTop: axis?.top?.enabled ? `${labelHeight}px` : "0",
						}}
					>
						<slot name="axis-label-right" />
					</div>
				</div>
				<div
					class="chart-matrix__label-bottom-container"
					style={{
						marginLeft: `${
							axis?.left?.enabled ? labelWidth + labelLeftWidth : labelLeftWidth
						}px`,
						marginRight: `${
							axis?.right?.enabled
								? labelWidth + labelRightWidth
								: labelRightWidth
						}px`,
					}}
				>
					<slot name="axis-label-bottom" />
				</div>
			</Fragment>
		);
	};

	render() {
		if (!this.matrixRuntime) {
			return null;
		}

		const popoverOptions: Partial<HbrPopover> = {
			distance: 10,
			variant: "chart",
			...this.popoverOptions,
		};

		const gridBlock = this.renderChart();
		const controlBlock = this.matrixRuntime.generateControlPanel(
			this.onZooming,
			this.onModeChange,
			this.mode,
			this.fullConfig,
			this.gridSize.blockSize,
			this.controlRef,
			(el) => {
				this.controlRef = el;
			},
		);

		return (
			<Host>
				<hbr-chart-board
					type="bar"
					ref={(el) => {
						this.boardRef = el;
					}}
					isLoading={this.loading}
					isEmpty={!this.config.data?.length}
					style={{ width: this.width, height: this.height }}
					exportparts="empty-state-illustration, empty-state-image, loading-state-illustration, loading-state-image"
				>
					<hbr-popover
						{...popoverOptions}
						ref={(el) => {
							this.tooltipRef = el;
						}}
						part="popover"
						exportparts="base__popup:popover-popup, base__arrow:popover-arrow, body:popover-body"
						anchor=""
					>
						<div slot="content">{this.tooltipContent}</div>
					</hbr-popover>
					<div slot="header" part="header" class="chart-matrix__header">
						<slot name="header">
							<div>
								<slot name="header-title" />
							</div>
							<div>
								<slot name="header-action" />
							</div>
						</slot>
					</div>
					<div
						ref={(el) => {
							this.chartRef = el;
						}}
						class="--hbr-chart --matrix-chart"
						part="chart"
					>
						{gridBlock}
					</div>
					{controlBlock}
					<slot name="footer" slot="footer" />
					<slot name="loading-state" slot="loading-state" />
					<slot name="empty-state" slot="empty-state" />
				</hbr-chart-board>
			</Host>
		);
	}
}
